import React, { useState } from 'react';
import {
  Grid,
  Paper,
  Typography,
  Box,
  Button,
  Chip,
  Card,
  CardContent,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  IconButton,
} from '@mui/material';
import {
  Add,
  Edit,
  Print,
  Email,
  TrendingUp,
  Receipt,
  ShoppingCart,
  LocalShipping,
  CheckCircle,
  Pending,
} from '@mui/icons-material';
import {
  BarChart,
  Bar,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  Legend,
  ResponsiveContainer,
  PieChart,
  Pie,
  Cell,
} from 'recharts';

const Sales = () => {
  const salesByCategory = [
    { category: 'Samossas', sales: 45000, orders: 45, color: '#0088FE' },
    { category: 'Spring Rolls', sales: 38000, orders: 32, color: '#00C49F' },
    { category: 'Sorvetes 300ml', sales: 28000, orders: 120, color: '#FFBB28' },
    { category: 'Sorvetes 5L', sales: 52000, orders: 65, color: '#FF8042' },
    { category: 'Recheios', sales: 15000, orders: 25, color: '#8884D8' },
  ];

  const salesByLocation = [
    { location: 'Beira', sales: 120000, clients: 45 },
    { location: 'Chimoio', sales: 75000, clients: 18 },
    { location: 'Tete', sales: 45000, clients: 12 },
    { location: 'Manga', sales: 25000, clients: 8 },
    { location: 'Songo', sales: 15000, clients: 3 },
  ];

  const recentSales = [
    {
      id: 1,
      orderId: 'ORD-001',
      client: 'China Mall',
      date: '2024-01-15',
      amount: 'MZN 4,500',
      status: 'delivered',
      deliveryId: 'DEL-001',
      deliveryStatus: 'completed',
    },
    {
      id: 2,
      orderId: 'ORD-002',
      client: 'VIP Spar Beira',
      date: '2024-01-15',
      amount: 'MZN 8,200',
      status: 'processing',
      deliveryId: 'DEL-002',
      deliveryStatus: 'in-transit',
    },
    {
      id: 3,
      orderId: 'ORD-003',
      client: 'Supermercado Mil Tete',
      date: '2024-01-14',
      amount: 'MZN 6,800',
      status: 'pending',
      deliveryId: 'DEL-003',
      deliveryStatus: 'scheduled',
    },
  ];

  return (
    <Box>
      <Box display="flex" justifyContent="space-between" alignItems="center" mb={3}>
        <Typography variant="h4">Sales Analytics</Typography>
        <Box>
          <Button variant="outlined" startIcon={<Print />} sx={{ mr: 1 }}>
            Export Report
          </Button>
          <Button variant="contained" startIcon={<Add />}>
            New Sale
          </Button>
        </Box>
      </Box>

      <Grid container spacing={3}>
        <Grid item xs={12}>
          <Grid container spacing={2}>
            <Grid item xs={12} sm={6} md={3}>
              <Card>
                <CardContent>
                  <Box display="flex" alignItems="center">
                    <TrendingUp sx={{ mr: 1, color: 'success.main', fontSize: 40 }} />
                    <Box>
                      <Typography variant="h5">MZN 178,900</Typography>
                      <Typography variant="caption" color="textSecondary">
                        Total Revenue
                      </Typography>
                    </Box>
                  </Box>
                </CardContent>
              </Card>
            </Grid>
            <Grid item xs={12} sm={6} md={3}>
              <Card>
                <CardContent>
                  <Box display="flex" alignItems="center">
                    <ShoppingCart sx={{ mr: 1, color: 'primary.main', fontSize: 40 }} />
                    <Box>
                      <Typography variant="h5">156</Typography>
                      <Typography variant="caption" color="textSecondary">
                        Total Orders
                      </Typography>
                    </Box>
                  </Box>
                </CardContent>
              </Card>
            </Grid>
            <Grid item xs={12} sm={6} md={3}>
              <Card>
                <CardContent>
                  <Box display="flex" alignItems="center">
                    <CheckCircle sx={{ mr: 1, color: 'success.main', fontSize: 40 }} />
                    <Box>
                      <Typography variant="h5">142</Typography>
                      <Typography variant="caption" color="textSecondary">
                        Completed
                      </Typography>
                    </Box>
                  </Box>
                </CardContent>
              </Card>
            </Grid>
            <Grid item xs={12} sm={6} md={3}>
              <Card>
                <CardContent>
                  <Box display="flex" alignItems="center">
                    <Pending sx={{ mr: 1, color: 'warning.main', fontSize: 40 }} />
                    <Box>
                      <Typography variant="h5">14</Typography>
                      <Typography variant="caption" color="textSecondary">
                        Pending
                      </Typography>
                    </Box>
                  </Box>
                </CardContent>
              </Card>
            </Grid>
          </Grid>
        </Grid>

        <Grid item xs={12} md={6}>
          <Paper sx={{ p: 2, height: 400 }}>
            <Typography variant="h6" gutterBottom>
              Sales by Product Category
            </Typography>
            <ResponsiveContainer width="100%" height="90%">
              <PieChart>
                <Pie
                  data={salesByCategory}
                  cx="50%"
                  cy="50%"
                  labelLine={false}
                  label={({ category, percent }) => `${category}: ${(percent * 100).toFixed(0)}%`}
                  outerRadius={100}
                  fill="#8884d8"
                  dataKey="sales"
                >
                  {salesByCategory.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={entry.color} />
                  ))}
                </Pie>
                <Tooltip formatter={(value) => `MZN ${value.toLocaleString()}`} />
                <Legend />
              </PieChart>
            </ResponsiveContainer>
          </Paper>
        </Grid>

        <Grid item xs={12} md={6}>
          <Paper sx={{ p: 2, height: 400 }}>
            <Typography variant="h6" gutterBottom>
              Sales by Location
            </Typography>
            <ResponsiveContainer width="100%" height="90%">
              <BarChart data={salesByLocation}>
                <CartesianGrid strokeDasharray="3 3" />
                <XAxis dataKey="location" />
                <YAxis />
                <Tooltip formatter={(value) => `MZN ${value.toLocaleString()}`} />
                <Legend />
                <Bar dataKey="sales" fill="#8884d8" name="Sales (MZN)" />
                <Bar dataKey="clients" fill="#82ca9d" name="Clients" />
              </BarChart>
            </ResponsiveContainer>
          </Paper>
        </Grid>

        <Grid item xs={12}>
          <Paper sx={{ p: 2 }}>
            <Box display="flex" justifyContent="space-between" alignItems="center" mb={2}>
              <Typography variant="h6">Recent Sales</Typography>
              <Button size="small" startIcon={<Email />}>
                Email Report
              </Button>
            </Box>
            <TableContainer>
              <Table>
                <TableHead>
                  <TableRow>
                    <TableCell>Order ID</TableCell>
                    <TableCell>Client</TableCell>
                    <TableCell>Date</TableCell>
                    <TableCell>Amount</TableCell>
                    <TableCell>Status</TableCell>
                    <TableCell>Delivery Status</TableCell>
                    <TableCell>Actions</TableCell>
                  </TableRow>
                </TableHead>
                <TableBody>
                  {recentSales.map((sale) => (
                    <TableRow key={sale.id}>
                      <TableCell>
                        <Typography variant="body2" fontWeight="medium">
                          {sale.orderId}
                        </Typography>
                      </TableCell>
                      <TableCell>{sale.client}</TableCell>
                      <TableCell>{sale.date}</TableCell>
                      <TableCell>
                        <Typography fontWeight="bold">{sale.amount}</Typography>
                      </TableCell>
                      <TableCell>
                        <Chip
                          label={sale.status}
                          size="small"
                          color={
                            sale.status === 'delivered'
                              ? 'success'
                              : sale.status === 'processing'
                              ? 'primary'
                              : 'default'
                          }
                        />
                      </TableCell>
                      <TableCell>
                        <Chip
                          label={sale.deliveryStatus}
                          size="small"
                          color={
                            sale.deliveryStatus === 'completed'
                              ? 'success'
                              : sale.deliveryStatus === 'in-transit'
                              ? 'warning'
                              : sale.deliveryStatus === 'scheduled'
                              ? 'info'
                              : 'default'
                          }
                        />
                      </TableCell>
                      <TableCell>
                        <IconButton size="small">
                          <Edit />
                        </IconButton>
                        <IconButton size="small">
                          <Receipt />
                        </IconButton>
                      </TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </TableContainer>
          </Paper>
        </Grid>
      </Grid>
    </Box>
  );
};

export default Sales;