import React, { useState } from 'react';
import {
  Grid,
  Paper,
  Typography,
  Box,
  Button,
  Chip,
  TextField,
  InputAdornment,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Card,
  CardContent,
  LinearProgress,
} from '@mui/material';
import {
  Search,
  Add,
  Warning,
  CheckCircle,
  Inventory as InventoryIcon,
  ShoppingBag,
} from '@mui/icons-material';

const Inventory = () => {
  const [searchTerm, setSearchTerm] = useState('');

  const inventoryItems = [
    { id: 1, materialId: 'SMPLATES', name: '12 Uni SAMOSSA PLATE', stock: 6000, reorder: 1000, supplier: 'TAO', status: 'sufficient' },
    { id: 2, materialId: '1KGTRIGO', name: '1KG TRIGO', stock: 67, reorder: 20, supplier: 'PEMBE', status: 'low' },
    { id: 3, materialId: 'WHEYPD', name: 'WHEY POWDER', stock: 100000, reorder: 25000, supplier: 'NOVA SOL', status: 'sufficient' },
    { id: 4, materialId: 'PLMFAT', name: '1KG PALM FAT', stock: 215, reorder: 25, supplier: 'NOVA SOL', status: 'sufficient' },
    { id: 5, materialId: 'LEITCOND', name: '500ML LEITE CONDENSADO', stock: 5, reorder: 6, supplier: 'MELHOR', status: 'critical' },
  ];

  const filteredItems = inventoryItems.filter(item =>
    item.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
    item.materialId.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const getStockPercentage = (stock, reorder) => {
    const percentage = (stock / (reorder * 5)) * 100;
    return Math.min(100, percentage);
  };

  const getStatusColor = (status) => {
    switch (status) {
      case 'sufficient': return 'success';
      case 'low': return 'warning';
      case 'critical': return 'error';
      default: return 'default';
    }
  };

  return (
    <Box>
      <Box display="flex" justifyContent="space-between" alignItems="center" mb={3}>
        <Typography variant="h4">Inventory Management</Typography>
        <Button variant="contained" startIcon={<Add />}>
          Add New Item
        </Button>
      </Box>

      <Grid container spacing={3}>
        <Grid item xs={12}>
          <Paper sx={{ p: 2 }}>
            <Grid container spacing={2} alignItems="center">
              <Grid item xs={12} md={8}>
                <TextField
                  fullWidth
                  placeholder="Search inventory items..."
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                  InputProps={{
                    startAdornment: (
                      <InputAdornment position="start">
                        <Search />
                      </InputAdornment>
                    ),
                  }}
                />
              </Grid>
              <Grid item xs={12} md={4}>
                <Grid container spacing={1}>
                  <Grid item xs={4}>
                    <Card variant="outlined">
                      <CardContent sx={{ textAlign: 'center', py: 1 }}>
                        <Typography variant="h6">8</Typography>
                        <Typography variant="caption">Total Items</Typography>
                      </CardContent>
                    </Card>
                  </Grid>
                  <Grid item xs={4}>
                    <Card variant="outlined">
                      <CardContent sx={{ textAlign: 'center', py: 1 }}>
                        <Typography variant="h6" color="warning.main">3</Typography>
                        <Typography variant="caption">Low Stock</Typography>
                      </CardContent>
                    </Card>
                  </Grid>
                  <Grid item xs={4}>
                    <Card variant="outlined">
                      <CardContent sx={{ textAlign: 'center', py: 1 }}>
                        <Typography variant="h6" color="error.main">2</Typography>
                        <Typography variant="caption">Critical</Typography>
                      </CardContent>
                    </Card>
                  </Grid>
                </Grid>
              </Grid>
            </Grid>
          </Paper>
        </Grid>

        <Grid item xs={12}>
          <Paper sx={{ p: 2 }}>
            <Typography variant="h6" gutterBottom>
              Inventory Items
            </Typography>
            <TableContainer>
              <Table>
                <TableHead>
                  <TableRow>
                    <TableCell>Material ID</TableCell>
                    <TableCell>Name</TableCell>
                    <TableCell>Supplier</TableCell>
                    <TableCell>Current Stock</TableCell>
                    <TableCell>Reorder Point</TableCell>
                    <TableCell>Stock Level</TableCell>
                    <TableCell>Status</TableCell>
                  </TableRow>
                </TableHead>
                <TableBody>
                  {filteredItems.map((item) => (
                    <TableRow key={item.id}>
                      <TableCell>
                        <Typography variant="body2" fontWeight="medium">
                          {item.materialId}
                        </Typography>
                      </TableCell>
                      <TableCell>{item.name}</TableCell>
                      <TableCell>{item.supplier}</TableCell>
                      <TableCell>{item.stock.toLocaleString()}</TableCell>
                      <TableCell>{item.reorder.toLocaleString()}</TableCell>
                      <TableCell>
                        <Box sx={{ display: 'flex', alignItems: 'center' }}>
                          <Box sx={{ width: '100%', mr: 1 }}>
                            <LinearProgress
                              variant="determinate"
                              value={getStockPercentage(item.stock, item.reorder)}
                              color={getStatusColor(item.status)}
                              sx={{ height: 8, borderRadius: 4 }}
                            />
                          </Box>
                          <Typography variant="body2">
                            {getStockPercentage(item.stock, item.reorder).toFixed(0)}%
                          </Typography>
                        </Box>
                      </TableCell>
                      <TableCell>
                        <Chip
                          label={item.status.toUpperCase()}
                          size="small"
                          color={getStatusColor(item.status)}
                          icon={
                            item.status === 'sufficient' ? (
                              <CheckCircle />
                            ) : (
                              <Warning />
                            )
                          }
                        />
                      </TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </TableContainer>
          </Paper>
        </Grid>
      </Grid>
    </Box>
  );
};

export default Inventory;