import React, { useState } from 'react';
import {
  Grid,
  Paper,
  Typography,
  Box,
  Button,
  Chip,
  Card,
  CardContent,
  LinearProgress,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  IconButton,
} from '@mui/material';
import {
  PlayArrow,
  CheckCircle,
  Add,
  Factory,
  Warning,
  Schedule,
} from '@mui/icons-material';

const Production = () => {
  const [batches, setBatches] = useState([
    {
      id: 'BATCH-S5LVN-001',
      productId: 'S5LVN',
      productName: 'SORVET5L-VANILLA',
      quantity: 6,
      status: 'scheduled',
      productionDate: '2024-01-16',
      shelfLife: '6 months',
    },
    {
      id: 'BATCH-S5LCH-001',
      productId: 'S5LCH',
      productName: 'SORVET5L-CHOCOLATE',
      quantity: 6,
      status: 'scheduled',
      productionDate: '2024-01-16',
      shelfLife: '6 months',
    },
    {
      id: 'BATCH-S5LMA-001',
      productId: 'S5LMA',
      productName: 'SORVET5L-MARACUJA',
      quantity: 6,
      status: 'scheduled',
      productionDate: '2024-01-16',
      shelfLife: '6 months',
    },
    {
      id: 'BATCH-S5LBL-001',
      productId: 'S5LBL',
      productName: 'SORVET5L-BLUEBERRY',
      quantity: 1,
      status: 'scheduled',
      productionDate: '2024-01-16',
      shelfLife: '6 months',
    },
  ]);

  const productionStats = [
    { label: 'Batches Today', value: '24', change: '+8%' },
    { label: 'Completed', value: '18', change: '+12%' },
    { label: 'In Progress', value: '4', change: '-2%' },
    { label: 'Scheduled', value: '2', change: '0%' },
  ];

  const handleStartBatch = (batchId) => {
    setBatches(batches.map(batch =>
      batch.id === batchId ? { ...batch, status: 'in-progress' } : batch
    ));
  };

  const handleCompleteBatch = (batchId) => {
    setBatches(batches.map(batch =>
      batch.id === batchId ? { ...batch, status: 'completed' } : batch
    ));
  };

  return (
    <Box>
      <Box display="flex" justifyContent="space-between" alignItems="center" mb={3}>
        <Typography variant="h4">Production Management</Typography>
        <Button variant="contained" startIcon={<Add />}>
          Schedule Batch
        </Button>
      </Box>

      <Grid container spacing={3}>
        <Grid item xs={12}>
          <Grid container spacing={2}>
            {productionStats.map((stat, index) => (
              <Grid item xs={6} sm={3} key={index}>
                <Card>
                  <CardContent>
                    <Typography variant="h5">{stat.value}</Typography>
                    <Typography variant="caption" color="textSecondary">
                      {stat.label}
                    </Typography>
                  </CardContent>
                </Card>
              </Grid>
            ))}
          </Grid>
        </Grid>

        <Grid item xs={12}>
          <Paper sx={{ p: 2 }}>
            <Typography variant="h6" gutterBottom>
              Production Batches
            </Typography>
            <TableContainer>
              <Table>
                <TableHead>
                  <TableRow>
                    <TableCell>Batch ID</TableCell>
                    <TableCell>Product</TableCell>
                    <TableCell>Quantity</TableCell>
                    <TableCell>Status</TableCell>
                    <TableCell>Shelf Life</TableCell>
                    <TableCell>Actions</TableCell>
                  </TableRow>
                </TableHead>
                <TableBody>
                  {batches.map((batch) => (
                    <TableRow key={batch.id}>
                      <TableCell>
                        <Typography variant="body2" fontWeight="medium">
                          {batch.id}
                        </Typography>
                      </TableCell>
                      <TableCell>{batch.productName}</TableCell>
                      <TableCell>{batch.quantity} units</TableCell>
                      <TableCell>
                        <Chip
                          label={batch.status}
                          size="small"
                          color={
                            batch.status === 'completed'
                              ? 'success'
                              : batch.status === 'in-progress'
                              ? 'warning'
                              : batch.status === 'scheduled'
                              ? 'info'
                              : 'default'
                          }
                          icon={
                            batch.status === 'completed' ? (
                              <CheckCircle />
                            ) : batch.status === 'in-progress' ? (
                              <PlayArrow />
                            ) : (
                              <Schedule />
                            )
                          }
                        />
                      </TableCell>
                      <TableCell>{batch.shelfLife}</TableCell>
                      <TableCell>
                        {batch.status === 'scheduled' && (
                          <IconButton
                            size="small"
                            onClick={() => handleStartBatch(batch.id)}
                          >
                            <PlayArrow />
                          </IconButton>
                        )}
                        {batch.status === 'in-progress' && (
                          <IconButton
                            size="small"
                            onClick={() => handleCompleteBatch(batch.id)}
                          >
                            <CheckCircle />
                          </IconButton>
                        )}
                      </TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </TableContainer>
          </Paper>
        </Grid>
      </Grid>
    </Box>
  );
};

export default Production;