import React, { useState } from 'react';
import {
  Grid,
  Paper,
  Typography,
  Box,
  Button,
  Chip,
  Card,
  CardContent,
  IconButton,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Stepper,
  Step,
  StepLabel,
} from '@mui/material';
import {
  Add,
  Edit,
  LocalShipping,
  CheckCircle,
  Pending,
  Schedule,
  Warning,
  Map,
  Phone,
  Person,
  DirectionsCar,
} from '@mui/icons-material';

const Delivery = () => {
  const [activeStep, setActiveStep] = useState(0);
  const deliverySteps = ['Scheduled', 'Loading', 'In Transit', 'Delivered'];

  const deliveries = [
    {
      id: 'DEL-001',
      orderId: 'ORD-001',
      client: 'China Mall',
      driver: 'John Doe',
      vehicle: 'Truck BZ-123',
      route: 'Beira Center',
      status: 'delivered',
      departure: '08:00 AM',
      deliveryTime: '10:30 AM',
      notes: 'Delivered successfully',
    },
    {
      id: 'DEL-002',
      orderId: 'ORD-002',
      client: 'VIP Spar Beira',
      driver: 'Maria Silva',
      vehicle: 'Van BZ-456',
      route: 'Beira Suburbs',
      status: 'in-transit',
      departure: '09:00 AM',
      deliveryTime: 'Expected 12:00 PM',
      notes: 'On the way',
    },
    {
      id: 'DEL-003',
      orderId: 'ORD-003',
      client: 'Supermercado Mil Tete',
      driver: 'Antonio',
      vehicle: 'Truck T-789',
      route: 'Tete City',
      status: 'scheduled',
      departure: '06:00 AM',
      deliveryTime: 'Tomorrow',
      notes: 'Scheduled for tomorrow',
    },
  ];

  return (
    <Box>
      <Box display="flex" justifyContent="space-between" alignItems="center" mb={3}>
        <Typography variant="h4">Delivery Management</Typography>
        <Button variant="contained" startIcon={<Add />}>
          Schedule Delivery
        </Button>
      </Box>

      <Grid container spacing={3}>
        <Grid item xs={12}>
          <Grid container spacing={2}>
            <Grid item xs={6} sm={3}>
              <Card>
                <CardContent>
                  <Box display="flex" alignItems="center">
                    <LocalShipping sx={{ mr: 1, color: 'primary.main' }} />
                    <Box>
                      <Typography variant="h6">156</Typography>
                      <Typography variant="caption" color="textSecondary">
                        Total Deliveries
                      </Typography>
                    </Box>
                  </Box>
                </CardContent>
              </Card>
            </Grid>
            <Grid item xs={6} sm={3}>
              <Card>
                <CardContent>
                  <Box display="flex" alignItems="center">
                    <CheckCircle sx={{ mr: 1, color: 'success.main' }} />
                    <Box>
                      <Typography variant="h6">142</Typography>
                      <Typography variant="caption" color="textSecondary">
                        Completed
                      </Typography>
                    </Box>
                  </Box>
                </CardContent>
              </Card>
            </Grid>
            <Grid item xs={6} sm={3}>
              <Card>
                <CardContent>
                  <Box display="flex" alignItems="center">
                    <Pending sx={{ mr: 1, color: 'warning.main' }} />
                    <Box>
                      <Typography variant="h6">8</Typography>
                      <Typography variant="caption" color="textSecondary">
                        In Progress
                      </Typography>
                    </Box>
                  </Box>
                </CardContent>
              </Card>
            </Grid>
            <Grid item xs={6} sm={3}>
              <Card>
                <CardContent>
                  <Box display="flex" alignItems="center">
                    <Warning sx={{ mr: 1, color: 'error.main' }} />
                    <Box>
                      <Typography variant="h6">6</Typography>
                      <Typography variant="caption" color="textSecondary">
                        Delayed
                      </Typography>
                    </Box>
                  </Box>
                </CardContent>
              </Card>
            </Grid>
          </Grid>
        </Grid>

        <Grid item xs={12}>
          <Paper sx={{ p: 2 }}>
            <Box display="flex" justifyContent="space-between" alignItems="center" mb={2}>
              <Typography variant="h6">Active Deliveries</Typography>
              <Button size="small" startIcon={<Map />}>
                View Route Map
              </Button>
            </Box>
            <Stepper activeStep={activeStep} sx={{ mb: 3 }}>
              {deliverySteps.map((label) => (
                <Step key={label}>
                  <StepLabel>{label}</StepLabel>
                </Step>
              ))}
            </Stepper>
            <TableContainer>
              <Table>
                <TableHead>
                  <TableRow>
                    <TableCell>Delivery ID</TableCell>
                    <TableCell>Client</TableCell>
                    <TableCell>Driver</TableCell>
                    <TableCell>Vehicle</TableCell>
                    <TableCell>Status</TableCell>
                    <TableCell>Actions</TableCell>
                  </TableRow>
                </TableHead>
                <TableBody>
                  {deliveries.map((delivery) => (
                    <TableRow key={delivery.id}>
                      <TableCell>
                        <Typography variant="body2" fontWeight="medium">
                          {delivery.id}
                        </Typography>
                        <Typography variant="caption" color="textSecondary">
                          Order: {delivery.orderId}
                        </Typography>
                      </TableCell>
                      <TableCell>{delivery.client}</TableCell>
                      <TableCell>
                        <Box display="flex" alignItems="center">
                          <Person sx={{ fontSize: 16, mr: 0.5 }} />
                          {delivery.driver}
                        </Box>
                      </TableCell>
                      <TableCell>
                        <Box display="flex" alignItems="center">
                          <DirectionsCar sx={{ fontSize: 16, mr: 0.5 }} />
                          {delivery.vehicle}
                        </Box>
                      </TableCell>
                      <TableCell>
                        <Chip
                          label={delivery.status}
                          size="small"
                          color={
                            delivery.status === 'delivered'
                              ? 'success'
                              : delivery.status === 'in-transit'
                              ? 'warning'
                              : delivery.status === 'scheduled'
                              ? 'info'
                              : 'error'
                          }
                          icon={
                            delivery.status === 'delivered' ? (
                              <CheckCircle />
                            ) : delivery.status === 'in-transit' ? (
                              <LocalShipping />
                            ) : delivery.status === 'scheduled' ? (
                              <Schedule />
                            ) : (
                              <Warning />
                            )
                          }
                        />
                      </TableCell>
                      <TableCell>
                        <IconButton size="small">
                          <Edit />
                        </IconButton>
                        <IconButton size="small">
                          <Phone />
                        </IconButton>
                      </TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </TableContainer>
          </Paper>
        </Grid>
      </Grid>
    </Box>
  );
};

export default Delivery;