import React, { createContext, useState, useContext } from 'react';

const AuthContext = createContext();

export const useAuth = () => {
  return useContext(AuthContext);
};

export const AuthProvider = ({ children }) => {
  const [user, setUser] = useState(null); // Start as null (not logged in)

  // Demo users database (replace with real auth later)
  const demoUsers = [
    { id: 'mgrema', name: 'Michella Grema', email: 'mrsgrema@gmail.com', password: 'admin123', role: 'Admin', location: 'Main Office', active: true },
	 { id: 'mgrema', name: 'Kevin Grema', email: 'kgrema@gmail.com', password: 'admin123', role: 'Admin', location: 'Main Office', active: true },	
    { id: 'prod1', name: 'Production Manager', email: 'production@foodchampion.com', password: 'prod123', role: 'Production', location: 'Factory', active: true },
    { id: 'sales1', name: 'Sales Manager', email: 'sales@foodchampion.com', password: 'sales123', role: 'Sales', location: 'Office', active: true },
    { id: 'delivery1', name: 'Delivery Coordinator', email: 'delivery@foodchampion.com', password: 'delivery123', role: 'Delivery', location: 'Dispatch', active: true },
  ];

  const login = (email, password) => {
    console.log('Login attempted:', email);
    
    // Find user in demo database
    const foundUser = demoUsers.find(user => 
      user.email === email && user.password === password
    );
    
    if (foundUser) {
      setUser({
        id: foundUser.id,
        name: foundUser.name,
        email: foundUser.email,
        role: foundUser.role,
        location: foundUser.location,
        active: foundUser.active,
      });
      // Store in localStorage for persistence
      localStorage.setItem('foodChampionUser', JSON.stringify(foundUser));
      return true;
    }
    
    return false;
  };

  const logout = () => {
    setUser(null);
    localStorage.removeItem('foodChampionUser');
  };

  // Check if user is already logged in (from localStorage)
  React.useEffect(() => {
    const storedUser = localStorage.getItem('foodChampionUser');
    if (storedUser) {
      setUser(JSON.parse(storedUser));
    }
  }, []);

  const value = {
    user,
    login,
    logout,
    isAuthenticated: !!user,
  };

  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
};